import{_ as a,o as t,c as i,a3 as o}from"./chunks/framework.BwzYn71E.js";const f=JSON.parse('{"title":"二进制稳流器","description":"","frontmatter":{"translationSource":{"title":"二进制稳流器","archivedAt":"2026-11-23","url":"https://docs.qq.com/aio/DTmluZ1diWlpQZldw?p=XZVY2YJV9J2aDl6ik1qPtM","scope":"page"},"translationLang":"zh","head":[["link",{"rel":"canonical","href":"https://kokobird28144.github.io/endfield-skydoc/zh/binary-flow-stabilizer"}],["link",{"rel":"alternate","hreflang":"en","href":"https://kokobird28144.github.io/endfield-skydoc/binary-flow-stabilizer"}],["link",{"rel":"alternate","hreflang":"zh-CN","href":"https://kokobird28144.github.io/endfield-skydoc/zh/binary-flow-stabilizer"}],["link",{"rel":"alternate","hreflang":"x-default","href":"https://kokobird28144.github.io/endfield-skydoc/binary-flow-stabilizer"}]]},"headers":[],"relativePath":"zh/binary-flow-stabilizer.md","filePath":"zh/page-XZVY2YJV9J2aDl6ik1qPtM.md"}'),r={name:"zh/binary-flow-stabilizer.md"};function n(l,e,d,s,p,c){return t(),i("div",null,[...e[0]||(e[0]=[o('<div class="logistics-content"><h1 id="二进制稳流器" tabindex="-1">二进制稳流器 <a class="header-anchor" href="#二进制稳流器" aria-label="Permalink to &quot;二进制稳流器&quot;">​</a></h1><p class="page-updated" data-update-status="recorded"><span>本页内容更新：</span><a href="/endfield-skydoc/zh/changelog/capture-2026-11-23T06-44-45-722Z-4358a738" title="网站最近同步到本页内容变更的时间（北京时间），不代表源作者实际编辑时间。点击查看更新记录。" aria-label="本页内容更新：2026-11-23. 网站最近同步到本页内容变更的时间（北京时间），不代表源作者实际编辑时间。点击查看更新记录。"><time datetime="2026-11-23T06:44:47.018Z">2026-11-23</time></a><span class="page-updated-zone">（北京时间）</span></p><blockquote><p>源页面 ID：<code>XZVY2YJV9J2aDl6ik1qPtM</code> ｜ <a href="https://docs.qq.com/aio/DTmluZ1diWlpQZldw?p=XZVY2YJV9J2aDl6ik1qPtM" target="_blank" rel="noreferrer">在腾讯文档中打开</a></p></blockquote><p>具体内容参见<a href="/endfield-skydoc/zh/proof-of-the-minimum-configured-power-for-binary-flow-stabilizer-power">关于二进制稳流器控电的最低配置功率证明</a></p><p>结构简述：24/25限流+均匀二进制分流+三分分流</p><p>由于<a href="/endfield-skydoc/zh/error-propagation-in-serial-structures">串联结构的误差传播</a>，可以计算该结构的理论最大误差，再由<a href="/endfield-skydoc/zh/calculating-the-range-of-stored-energy">蓄电量极差计算</a>，可以计算该结构的最大电量极差，进而确定是否会出现断电问题</p><p>优点：电量极差可计算，精准控电无浪费，结构可控，设计简单</p><p>缺点：占地较大，计算繁琐，发电量基于结构，无法自动变化</p><p>各部分结构常见构造：</p><p><strong>24/25限流</strong></p><p><a href="/endfield-skydoc/zh/applications-of-some-theories">一些理论的应用实例</a></p><p>迟滞输出(4n卡1s)实现，误差为(n-1)/4n=(3-1)/4*3=1/6</p><p><strong>均匀二进制</strong></p><p><a href="/endfield-skydoc/zh/tianshi-academy-and-chishi-academy-of-sciences-online-documentation">天师府学院及赤石科学院在线文档</a>，误差为<a href="/endfield-skydoc/zh/theoretical-lower-bound-for-perfect-uniformity">完美均匀的理论下界</a></p><p>快速计算：3200<em>40</em>0.5<em>24/25</em>p*1/3=x，均匀二进制比例p=还需耗电/发电量x/(5x2^12)</p><p><strong>三分分流</strong></p><p>三出口分流器三分结构，误差为0</p><p>以24/25迟滞输出实现的该设备误差为M_dev &lt; 6(K-2)/(K-1)，猜测误差应当&lt;1</p></div>',1)])])}const k=a(r,[["render",n]]);export{f as __pageData,k as default};
